    hosts: Array.isArray(saved.network_hosts) ? saved.network_hosts.join("\n") : "",
  });
  const [error, setError] = useState("");
  const change = <K extends keyof OperatorForm>(key: K, value: OperatorForm[K]) => setForm((old) => ({ ...old, [key]: value }));
