.model-menu-actions { display: flex; flex-direction: column; gap: 2px; padding: 6px; border-top: 1px solid var(--color-border-subtle); }
.model-menu-actions button { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 30px; padding: 5px 8px; border: 0; border-radius: 7.5px; background: none; text-align: left; font-size: 13px; line-height: 20px; }
.model-menu-actions button:hover { background: var(--color-background-secondary-ghost-hover); }
.send-button { display: grid; place-items: center; width: 28px; height: 28px; flex: none; padding: 0; border: 0; border-radius: 50%; background: var(--color-text); color: var(--app-color-background-surface); }
.send-button:disabled { opacity: 1; background: var(--color-background-secondary-ghost-hover); color: var(--muted); }

/* Activity text, measured nested disclosure, concrete output cards. */
.event-group { margin: 0 auto 16px; color: var(--muted); font-size: 14px; line-height: 21px; }
.event-line, .event-record { margin: 0; }
.event-group > summary, .event-line > summary, .event-record > summary { display: inline-flex; align-items: center; vertical-align: top; gap: 4px; max-width: 100%; height: 21px; padding: 0; border: 0; border-radius: 0; background: none; color: var(--muted); font-size: 14px; line-height: 21px; font-weight: 400; list-style: none; }
.event-group > summary::-webkit-details-marker, .event-line > summary::-webkit-details-marker, .event-record > summary::-webkit-details-marker, .approval-details > summary::-webkit-details-marker { display: none; }
.event-group > summary:hover, .event-line > summary:hover, .event-record > summary:hover { color: var(--color-text); }
.event-group > summary svg, .event-line > summary svg, .event-record > summary svg { flex: none; width: 16px; height: 16px; }
.event-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.event-mode { color: inherit; font-size: 12px; }
.event-failed { color: var(--color-status-error); }
.event-line.unknown .event-failed { color: var(--color-status-warning); }
[data-chevron] { transition: transform .15s var(--ease-out); }
[aria-expanded="true"] > [data-chevron] { transform: rotate(90deg); }
.detail-collapsible { height: 0; opacity: 0; overflow: hidden; margin-inline-start: -8px; padding-inline-start: 8px; transition: height .15s var(--ease-out), opacity .15s var(--ease-out); }
.event-detail { position: relative; display: flex; flex-direction: column; gap: 12px; padding: 12px 0 0 24px; color: var(--muted); font-size: 13px; line-height: 20px; }
.event-detail::before { position: absolute; content: ""; top: 12px; bottom: 0; left: 8px; width: 1px; background: var(--color-border); pointer-events: none; }
.event-line .event-detail { gap: 8px; padding: 8px 0 4px 24px; }
.event-line .event-detail::before { top: 8px; }
.event-detail p { margin: 0; }
.event-detail .text-button { align-self: flex-start; text-align: left; }
.event-detail dl { display: block; margin: 8px 0; }
.event-detail dl > div { display: flex; gap: 8px; }
