.event-detail dd { flex: 1; min-width: 0; overflow-wrap: anywhere; }
.event-detail small { font-size: 12px; line-height: 16px; }
.event-record-content { display: flex; flex-direction: column; gap: 8px; padding: 8px 0 4px 24px; }
.event-origin { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; line-height: 18px; }
.command-card { display: flex; flex-direction: column; min-width: 0; overflow: hidden; border: 0.8px solid var(--color-border-strong); border-radius: 12.5px; background: var(--color-background-command); }
.command-card > header { padding: 4px 8px; color: var(--muted); font-size: 13px; line-height: 18px; }
