.timeline-update:not(.approval-card) { padding-inline: 4px; border: 0; border-bottom: 1px solid var(--color-border-subtle); border-radius: 0; }
.approval-card { display: grid; grid-template-columns: minmax(0,1fr) auto; gap: 10px 16px; padding: 16px; }
.approval-summary { grid-column: 1 / -1; display: flex; justify-content: space-between; gap: 12px; padding: 0; border: 0; background: none; text-align: left; }
