.settings-back:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.settings-search { display: flex; align-items: center; gap: 8px; height: 34px; flex: none; margin-top: -8px; padding: 6px 12px; border: 1px solid transparent; border-radius: 18px; background: var(--color-background-nav-active); color: var(--muted); }
.settings-search:focus-within { border-color: var(--color-border-strong); background: var(--app-color-background-surface); }
.settings-search svg { flex: none; width: 16px; height: 16px; }
.settings-search input { width: 100%; min-width: 0; padding: 0; border: 0; outline: 0; background: none; font-size: 13px; line-height: 20px; }
.settings-search input::-webkit-search-cancel-button, .quest-search input::-webkit-search-cancel-button { -webkit-appearance: none; }
.settings-search-clear { display: grid; place-items: center; width: 22px; height: 22px; flex: none; padding: 0; border: 0; border-radius: 50%; background: none; color: var(--muted); }
