.settings-nav-item { display: flex; align-items: center; gap: 8px; width: 100%; height: 30px; padding: 5px 8px; border: 0; border-radius: 12.5px; background: none; text-align: start; font-size: 13px; line-height: 18.5714px; }
.settings-nav-item:hover, .settings-nav-item.active { background: var(--color-background-secondary-ghost-hover); }
